import{_ as a,o as t,c as l,a3 as o}from"./chunks/framework.BPaanrMb.js";const u=JSON.parse('{"title":"WheelOS 项目与理念","description":"WheelOS 的产品与知识定位、证据优先原则，以及商业解决方案与工程验证的边界。","frontmatter":{"title":"WheelOS 项目与理念","description":"WheelOS 的产品与知识定位、证据优先原则，以及商业解决方案与工程验证的边界。","content_type":"overview","status":"仓库事实","keywords":["WheelOS","Wheel.OS","Wheel.App","证据优先","自动驾驶"]},"headers":[],"relativePath":"about/wheelos.md","filePath":"about/wheelos.md","lastUpdated":1794551845000}'),r={name:"about/wheelos.md"};function i(s,e,n,h,d,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="wheelos-项目与理念" tabindex="-1">WheelOS：项目与理念 <a class="header-anchor" href="#wheelos-项目与理念" aria-label="Permalink to &quot;WheelOS：项目与理念&quot;">​</a></h1><h2 id="wheelos-是什么" tabindex="-1">WheelOS 是什么？ <a class="header-anchor" href="#wheelos-是什么" aria-label="Permalink to &quot;WheelOS 是什么？&quot;">​</a></h2><p>WheelOS 同时提供面向园区低速自动驾驶的软硬件解决方案，以及面向开发者和 AI Agent 的工程知识与验证记录。公开内容分为产品与知识两条主线：</p><ul><li><strong>Wheel.OS</strong>：核心中间件、消息接口、传感器驱动、车辆底盘，以及配置、可视化和底盘适配工具。</li><li><strong>Wheel.App</strong>：定位、感知、预测、规划、控制，以及标定、时间同步、车辆动力学和 Carla 集成工具。</li></ul><p>这些名称和能力范围来自仓库的路线图。它们描述的是项目规划或目标，除非有源码、发布物或实践记录支持，否则不能直接理解为已交付能力。可采购的一体化套件则通过解决方案页面和正式报价单独描述。</p><h2 id="理念-工程证据优先" tabindex="-1">理念：工程证据优先 <a class="header-anchor" href="#理念-工程证据优先" aria-label="Permalink to &quot;理念：工程证据优先&quot;">​</a></h2><p>WheelOS Docs 不是单纯的产品宣传页，也不是只罗列术语的文档站，而是一个可被 AI 查询的工程知识与产品知识系统：</p><ol><li><strong>问题优先</strong>：从车辆现象和工程约束出发，而不是从术语目录出发。</li><li><strong>证据分层</strong>：明确区分仓库事实、设计建议、已验证实践、产品配置和待验证假设。</li><li><strong>可复现</strong>：记录版本、硬件、数据集、配置、命令、指标和结果。</li><li><strong>允许失败</strong>：失败实验同样重要，它能避免 AI 重复推荐无效方案。</li><li><strong>不越界</strong>：仿真验证、封闭场地验证和量产安全论证是不同等级，不能互相替代。</li><li><strong>双语对等</strong>：中文和英文页面保持相同事实、数字、状态和限制。</li></ol><h2 id="当前已知范围" tabindex="-1">当前已知范围 <a class="header-anchor" href="#当前已知范围" aria-label="Permalink to &quot;当前已知范围&quot;">​</a></h2><p>目前仓库主要包含社区组织信息和路线图，自动驾驶模块的实现细节与真实车辆验证记录仍在持续补充。因此，AI 使用本仓库回答问题时，应把“路线图中的目标”与“代码或实验已经证明的能力”严格分开。</p><h2 id="商业解决方案与工程证据的边界" tabindex="-1">商业解决方案与工程证据的边界 <a class="header-anchor" href="#商业解决方案与工程证据的边界" aria-label="Permalink to &quot;商业解决方案与工程证据的边界&quot;">​</a></h2><p><a href="/solutions/integrated-autonomous-driving-kit">一体化自动驾驶开发套件</a>是 WheelOS 面向项目的软硬件解决方案页面，用于说明配置、交付范围和集成条件。它不能替代 <code>evidence/registry.json</code> 中的实验记录，也不表示套件已在所有车型、场地或法规环境下完成量产验证。项目适用性、最终配置和报价需单独确认。</p><h2 id="相关入口" tabindex="-1">相关入口 <a class="header-anchor" href="#相关入口" aria-label="Permalink to &quot;相关入口&quot;">​</a></h2><ul><li><a href="/solutions/">自动驾驶解决方案</a></li><li><a href="/about/system-map">系统地图</a></li><li><a href="/roadmap/2025">路线图</a></li><li><a href="/organization/organization">组织结构</a></li></ul>',14)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
